'use strict';

const APP_VERSION = '0.5.1-alpha';
const PROTOCOL_VERSION = 3;
const DEPLOYMENT = window.SECUREBRIDGE_DEPLOYMENT || null;
const DEPLOYMENT_ID = DEPLOYMENT?.deploymentId || '';
const ALLOWED_PATH = DEPLOYMENT?.allowedPath || '';
const API = DEPLOYMENT?.apiUrl || '';
const ARGON_MEMORY_KB = 65536;
const ARGON_ITERS = 3;
const ARGON_PARALLELISM = 1;
const SERVER_TTL_SECONDS = 7 * 24 * 3600;
const MAX_TEXT_BYTES = 1800;
const PAD_BYTES = 6144;
const SYNC_INTERVAL_MS = 4000;
const SLOT_LOOKAHEAD = 8;
const FOREGROUND_BATCH_CONTACTS = 16;
const FOREGROUND_PEEK_SLOTS = 128;
const MAX_DR_SKIP = 64;
const REPLAY_CACHE_MAX = 512;
const PAIR_REPLAY_MAX = 128;
const PAIR_MAX_AGE_MS = 5 * 60 * 1000;
const NATIVE = !!(window.SecureBridge && typeof window.SecureBridge.isNativeVault === 'function' && window.SecureBridge.isNativeVault());

const $app = document.getElementById('app');
const enc = new TextEncoder();
const dec = new TextDecoder();

const state = {
  mode: 'locked', vault: null, vaultKey: null, vaultRef: null, currentUid: null,
  pendingPair: null, currentContactId: null, currentGroupId: null,
  inactivityTimer: null, hiddenTimer: null, syncTimer: null, syncing: false,
  view: {type:'entry', id:null}, syncCursor: 0,
};

const EMOJIS = ['🦊','🌙','🔑','🍋','🚀','🐙','🌿','⭐','🐼','🍓','🎈','🧩','🐢','🌈','🪐','🦉','🍀','🐳','🧸','🍉','🛡️','🎲','🐝','🌻','🪶','🍄','🐬','🦖','🧊','🪁','🎧','🌵'];

function b64(bytes){let s='';const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);for(let i=0;i<a.length;i++)s+=String.fromCharCode(a[i]);return btoa(s);}
function unb64(s){const raw=atob(String(s||''));const a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a;}
function hex(bytes){return[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function unhex(s){s=String(s||'');if(!/^[0-9a-f]*$/i.test(s)||s.length%2)throw new Error('Hex invalide.');const out=new Uint8Array(s.length/2);for(let i=0;i<out.length;i++)out[i]=parseInt(s.slice(i*2,i*2+2),16);return out;}
function rnd(n=32){const a=new Uint8Array(n);crypto.getRandomValues(a);return a;}
function rid(n=16){return hex(rnd(n));}
function concat(...arrs){const arrays=arrs.map(a=>a instanceof Uint8Array?a:new Uint8Array(a));const out=new Uint8Array(arrays.reduce((n,a)=>n+a.length,0));let o=0;for(const a of arrays){out.set(a,o);o+=a.length;}return out;}
function normUid(uid){return String(uid||'').replace(/[^0-9a-f]/gi,'').toUpperCase();}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function byteLen(s){return enc.encode(s).length;}
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
function unique(a){return[...new Set(a)];}
function clone(o){return JSON.parse(JSON.stringify(o));}
function ctEqual(a,b){try{const x=unb64(a),y=unb64(b);if(x.length!==y.length)return false;let d=0;for(let i=0;i<x.length;i++)d|=x[i]^y[i];return d===0;}catch{return false;}}

async function sha256(data){return new Uint8Array(await crypto.subtle.digest('SHA-256',data instanceof Uint8Array?data:enc.encode(String(data))));}
async function hmacRaw(keyBytes,data){const k=await crypto.subtle.importKey('raw',keyBytes,{name:'HMAC',hash:'SHA-256'},false,['sign']);return new Uint8Array(await crypto.subtle.sign('HMAC',k,data instanceof Uint8Array?data:enc.encode(String(data))));}
async function hkdf(ikm,salt,info,len=32){const k=await crypto.subtle.importKey('raw',ikm,'HKDF',false,['deriveBits']);return new Uint8Array(await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt,info:enc.encode(info)},k,len*8));}
async function aesEncrypt(keyBytes,plainBytes,aad=''){const key=await crypto.subtle.importKey('raw',keyBytes,'AES-GCM',false,['encrypt']);const iv=rnd(12);const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:enc.encode(aad)},key,plainBytes);return{iv:b64(iv),ct:b64(ct)};}
async function aesDecrypt(keyBytes,box,aad=''){const key=await crypto.subtle.importKey('raw',keyBytes,'AES-GCM',false,['decrypt']);const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(box.iv),additionalData:enc.encode(aad)},key,unb64(box.ct));return new Uint8Array(pt);}

function requireNative(){if(!NATIVE)throw new Error('SecureBridge Android est requis pour cette version.');}
function argon2id(value,saltB64){requireNative();const r=window.SecureBridge.argon2id(String(value),String(saltB64),ARGON_MEMORY_KB,ARGON_ITERS,ARGON_PARALLELISM,32);if(!r)throw new Error('Argon2id indisponible.');return unb64(r);}
function x25519KeyPair(){requireNative();const r=window.SecureBridge.x25519KeyPair();if(!r)throw new Error('X25519 indisponible.');return JSON.parse(r);}
function x25519Shared(priv,pub){requireNative();const r=window.SecureBridge.x25519Shared(priv,pub);if(!r)throw new Error('Accord X25519 impossible.');return unb64(r);}
function ed25519KeyPair(){requireNative();const r=window.SecureBridge.ed25519KeyPair();if(!r)throw new Error('Ed25519 indisponible.');return JSON.parse(r);}
function ed25519Sign(priv,text){requireNative();const r=window.SecureBridge.ed25519Sign(priv,b64(enc.encode(text)));if(!r)throw new Error('Signature Ed25519 impossible.');return r;}
function ed25519Verify(pub,text,sig){requireNative();return !!window.SecureBridge.ed25519Verify(pub,b64(enc.encode(text)),sig);}

// Le coffre logique est stocké dans le bundle natif, lui-même enveloppé par Android Keystore.
let nativeKvCache=null;
function loadNativeKv(){requireNative();if(nativeKvCache!==null)return nativeKvCache;try{nativeKvCache=JSON.parse(window.SecureBridge.loadKvJson()||'{}')||{};}catch{nativeKvCache={};}return nativeKvCache;}
function saveNativeKv(){requireNative();if(!window.SecureBridge.saveKvJson(JSON.stringify(nativeKvCache||{})))throw new Error('Écriture du coffre natif impossible.');}
async function kvGet(k){const o=loadNativeKv();return Object.prototype.hasOwnProperty.call(o,k)?o[k]:undefined;}
async function kvSet(k,v){const o=loadNativeKv();o[k]=v;saveNativeKv();}
async function kvClear(){nativeKvCache={};saveNativeKv();}
async function kvKeys(){return Object.keys(loadNativeKv());}

async function api(action,payload={}){
  if(!DEPLOYMENT_ID||!API)throw new Error('Déploiement web non configuré.');const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','Cache-Control':'no-store'},cache:'no-store',credentials:'omit',redirect:'error',body:JSON.stringify({deploymentId:DEPLOYMENT_ID,action,...payload})});
  let j={};try{j=await r.json();}catch{}
  if(!r.ok||j.ok===false)throw new Error(j.error||`Erreur serveur ${r.status}`);
  return j;
}
function fireAndForget(action,payload={}){api(action,payload).catch(()=>{});}

function renderShell(content,opts={}){const badge=NATIVE?'<span class="badge">local</span>':'';$app.innerHTML=`<div class="topbar"><div class="brand">${escapeHtml(opts.title||'Espace privé')} ${badge}</div>${opts.action||''}</div>${content}`;}
function msg(el,text,kind=''){if(el)el.innerHTML=`<div class="status ${kind}">${escapeHtml(text)}</div>`;}

// NFC privé : uniquement pour ouvrir SON coffre.
const nativeNfcWaiters=new Map();
window.__secureBridgeNfcResult=(requestId,uid,error)=>{const w=nativeNfcWaiters.get(requestId);if(!w)return;nativeNfcWaiters.delete(requestId);if(error)w.reject(new Error(String(error)));else if(uid)w.resolve(normUid(uid));else w.reject(new Error('Lecture NFC invalide.'));};
async function scanNfc(){requireNative();const id=rid(10);return new Promise((resolve,reject)=>{nativeNfcWaiters.set(id,{resolve,reject});try{window.SecureBridge.startNfcScan(id);}catch(e){nativeNfcWaiters.delete(id);reject(e);}setTimeout(()=>{const w=nativeNfcWaiters.get(id);if(w){nativeNfcWaiters.delete(id);reject(new Error('Aucun objet NFC détecté.'));}},32000);});}

// Pairing téléphone ↔ téléphone. Deux phases NFC : échange frais, puis preuve de possession anti-rejeu.
const nativePairWaiters=new Map();
window.__secureBridgePairResult=(requestId,payloadB64,error)=>{const w=nativePairWaiters.get(requestId);if(!w)return;nativePairWaiters.delete(requestId);if(error)w.reject(new Error(String(error)));else{try{w.resolve(JSON.parse(dec.decode(unb64(payloadB64))));}catch{w.reject(new Error('Réponse NFC de pairing invalide.'));}}};
async function nativePair(role,payload){requireNative();const requestId=rid(10),payloadB64=b64(enc.encode(JSON.stringify(payload)));return new Promise((resolve,reject)=>{nativePairWaiters.set(requestId,{resolve,reject});try{if(role==='host')window.SecureBridge.startPairingHost(requestId,payloadB64);else window.SecureBridge.startPairingReader(requestId,payloadB64);}catch(e){nativePairWaiters.delete(requestId);reject(e);}setTimeout(()=>{const w=nativePairWaiters.get(requestId);if(w){nativePairWaiters.delete(requestId);try{window.SecureBridge.cancelPairing();}catch{}reject(new Error('Pairing NFC expiré.'));}},65000);});}

function notificationGranted(){try{return NATIVE&&window.SecureBridge.notificationPermissionGranted();}catch{return false;}}
function requestNotificationPermission(){if(NATIVE)try{window.SecureBridge.requestNotificationPermission();}catch{}}
function disableBackgroundPolling(){if(NATIVE)try{window.SecureBridge.disableBackgroundPolling();}catch{}}
function apiAbsoluteUrl(){if(!API)throw new Error('API non configurée.');return new URL(API,location.href).href;}
function syncWakeState(){if(!NATIVE||state.mode!=='real'||!state.vault)return;try{const channels=state.vault.contacts.filter(c=>!c.decoy&&c.crypto?.transport).map(c=>({id:c.wakeId,chain:c.crypto.transport.recvSlotChain,counter:c.crypto.transport.recvCounter||0}));window.SecureBridge.configureBackgroundPolling(apiAbsoluteUrl(),JSON.stringify(channels));}catch{}}

async function ensureDeviceFactor(){requireNative();const test=window.SecureBridge.hmacDevice('BOOTSTRAP-v3');if(!test)throw new Error('Android Keystore indisponible.');}
async function deriveUnlock(uid,password,pin,meta,header){
  const a=window.SecureBridge.hmacDevice('TAG:'+normUid(uid)),b=window.SecureBridge.hmacDevice('DEVICE:'+meta.vaultId);if(!a||!b)throw new Error('Facteur Android Keystore indisponible.');
  const tagFactor=unb64(a),deviceFactor=unb64(b),passFactor=argon2id('PWD\0'+password,meta.passwordSalt),pinFactor=argon2id('PIN\0'+pin,header.pinSalt);
  const out=await hkdf(concat(tagFactor,passFactor,pinFactor,deviceFactor),unb64(header.vaultSalt),'PRIVATE-VAULT/v3',32);
  tagFactor.fill(0);deviceFactor.fill(0);passFactor.fill(0);pinFactor.fill(0);return out;
}
async function saveVault(){if(!state.vault||!state.vaultKey||!state.vaultRef)return;purgeExpired(false);const bytes=enc.encode(JSON.stringify(state.vault));const box=await aesEncrypt(state.vaultKey,bytes,'VAULT:'+state.vaultRef);await kvSet('vault:'+state.vaultRef,box);syncWakeState();}
async function loadVault(ref,keyBytes){const box=await kvGet('vault:'+ref);if(!box)throw new Error('Coffre absent.');const pt=await aesDecrypt(keyBytes,box,'VAULT:'+ref);return JSON.parse(dec.decode(pt));}
async function identityFingerprint(signPub){return hex(await sha256(unb64(signPub)));}

function normalizeVault(v){
  v.contacts=v.contacts||[];v.messages=v.messages||[];v.groups=v.groups||[];v.groupMessages=v.groupMessages||[];v.pendingGroups=v.pendingGroups||[];v.seenPairings=v.seenPairings||[];v.settings=v.settings||{autoLockSeconds:180,backgroundLockSeconds:30};
  return v;
}

async function setupVault(uid,password,pinNormal,pinDuress){
  requireNative();if(password.length<12)throw new Error('Mot de passe : 12 caractères minimum.');
  if(!/^\d{8,}$/.test(pinNormal)||!/^\d{8,}$/.test(pinDuress))throw new Error('PIN normal et contrainte : 8 chiffres minimum.');
  if(pinNormal===pinDuress)throw new Error('Les deux PIN doivent être différents.');let diff=0;for(let i=0;i<Math.min(pinNormal.length,pinDuress.length);i++)if(pinNormal[i]!==pinDuress[i])diff++;if(diff<3)throw new Error('Les PIN sont trop proches.');
  const installSent=await kvGet('stat:installSent');await kvClear();if(installSent)await kvSet('stat:installSent',true);await ensureDeviceFactor();disableBackgroundPolling();
  const meta={version:3,appVersion:APP_VERSION,vaultId:rid(16),passwordSalt:b64(rnd(16)),kdf:{name:'Argon2id',memoryKb:ARGON_MEMORY_KB,iterations:ARGON_ITERS,parallelism:ARGON_PARALLELISM},headers:[]};
  const identity=ed25519KeyPair(),fp=await identityFingerprint(identity.public),now=Date.now();
  const realVault=normalizeVault({version:3,kind:'real',createdAt:now,identity:{signPrivate:identity.private,signPublic:identity.public,fingerprint:fp},contacts:[],messages:[],groups:[],groupMessages:[],pendingGroups:[],seenPairings:[],settings:{autoLockSeconds:180,backgroundLockSeconds:30},security:{protocol:'DR-v3',kdf:'Argon2id',pairing:'Ed25519+X25519-2phase'}});
  const decoyVault=normalizeVault({version:3,kind:'decoy',createdAt:now,identity:null,contacts:[{id:'d1',name:'Marc',decoy:true},{id:'d2',name:'Alex',decoy:true},{id:'d3',name:'Camille',decoy:true}],messages:[{id:rid(16),contactId:'d1',dir:'in',text:'Ok pour demain 👍',ts:now-7200000,expiresAt:0},{id:rid(16),contactId:'d2',dir:'out',text:'Merci !',ts:now-3600000,expiresAt:0},{id:rid(16),contactId:'d3',dir:'in',text:'À plus tard 😊',ts:now-900000,expiresAt:0}],groups:[],groupMessages:[],pendingGroups:[],seenPairings:[],settings:{autoLockSeconds:180,backgroundLockSeconds:30}});
  for(const e of [{kind:'real',pin:pinNormal,vault:realVault},{kind:'decoy',pin:pinDuress,vault:decoyVault}]){
    const ref=rid(16),vaultKey=rnd(32),pinSalt=rnd(16),vaultSalt=rnd(16),header={id:rid(8),pinSalt:b64(pinSalt),vaultSalt:b64(vaultSalt),box:null};
    const unlock=await deriveUnlock(uid,password,e.pin,meta,header),descriptor={kind:e.kind,vaultRef:ref,vaultKey:b64(vaultKey)};
    header.box=await aesEncrypt(unlock,enc.encode(JSON.stringify(descriptor)),'HEADER:'+header.id);unlock.fill(0);meta.headers.push(header);await kvSet('vault:'+ref,await aesEncrypt(vaultKey,enc.encode(JSON.stringify(e.vault)),'VAULT:'+ref));vaultKey.fill(0);
  }
  if(rnd(1)[0]&1)meta.headers.reverse();await kvSet('meta',meta);state.currentUid=null;fireAndForget('stat_event',{event:'vault_created',version:APP_VERSION});
}

async function unlockVault(uid,password,pin){
  const meta=await kvGet('meta');if(!meta||meta.version!==3)throw new Error('Aucun coffre v0.5 compatible. Une installation propre est requise après la v0.4.');
  for(const header of meta.headers||[]){try{const unlock=await deriveUnlock(uid,password,pin,meta,header),pt=await aesDecrypt(unlock,header.box,'HEADER:'+header.id);unlock.fill(0);const d=JSON.parse(dec.decode(pt)),vk=unb64(d.vaultKey),vault=normalizeVault(await loadVault(d.vaultRef,vk));state.mode=d.kind;state.vault=vault;state.vaultKey=vk;state.vaultRef=d.vaultRef;state.currentUid=normUid(uid);if(d.kind==='decoy'){await duressWipe(meta,header.id,d.vaultRef);disableBackgroundPolling();}purgeExpired(false);await saveVault();startSyncLoop();return;}catch{}}
  throw new Error('Impossible d’ouvrir cet espace.');
}
async function duressWipe(meta,keepHeaderId,keepVaultRef){const keys=await kvKeys();for(const k of keys){if(typeof k==='string'&&k.startsWith('vault:')&&k!==('vault:'+keepVaultRef)){const old=await kvGet(k),ctLen=old?.ct?unb64(old.ct).length:512;try{await kvSet(k,{iv:b64(rnd(12)),ct:b64(rnd(Math.max(64,ctLen)))});}catch{}}}meta.headers=meta.headers.map(h=>h.id===keepHeaderId?h:{...h,box:{iv:b64(rnd(12)),ct:b64(rnd(Math.max(48,h.box?.ct?unb64(h.box.ct).length:128)))}});await kvSet('meta',meta);}
async function verifyCurrentCredentials(uid,password,pin){const meta=await kvGet('meta');if(!meta)throw new Error('Aucun espace local.');for(const header of meta.headers||[]){try{const unlock=await deriveUnlock(uid,password,pin,meta,header),pt=await aesDecrypt(unlock,header.box,'HEADER:'+header.id);unlock.fill(0);const d=JSON.parse(dec.decode(pt));if(d.kind===state.mode)return true;}catch{}}throw new Error('Vérification impossible.');}
async function overwriteLocalVaultsBestEffort(){try{const keys=await kvKeys();for(const k of keys){if(typeof k==='string'&&k.startsWith('vault:')){const old=await kvGet(k),ctLen=old?.ct?unb64(old.ct).length:1024;try{await kvSet(k,{iv:b64(rnd(12)),ct:b64(rnd(Math.max(128,ctLen)))});}catch{}}}const meta=await kvGet('meta');if(meta?.headers){meta.headers=meta.headers.map(h=>({...h,box:{iv:b64(rnd(12)),ct:b64(rnd(Math.max(64,h.box?.ct?unb64(h.box.ct).length:256)))}}));try{await kvSet('meta',meta);}catch{}}}catch{}}
async function destroyLocalSpace(){stopSyncLoop();clearAutoLockTimers();disableBackgroundPolling();await overwriteLocalVaultsBestEffort();try{window.SecureBridge.destroyAll();}catch{}nativeKvCache={};state.mode='locked';state.vault=null;state.vaultKey=null;state.vaultRef=null;state.currentUid=null;state.pendingPair=null;state.currentContactId=null;state.currentGroupId=null;}

function purgeExpired(save=true){if(!state.vault)return;const now=Date.now();let changed=false;for(const key of ['messages','groupMessages']){const a=state.vault[key]||[],b=a.filter(m=>!m.expiresAt||m.expiresAt>now);if(b.length!==a.length){state.vault[key]=b;changed=true;}}if(save&&changed)saveVault().catch(()=>{});}
function clearAutoLockTimers(){if(state.inactivityTimer){clearTimeout(state.inactivityTimer);state.inactivityTimer=null;}if(state.hiddenTimer){clearTimeout(state.hiddenTimer);state.hiddenTimer=null;}}
function autoLockSeconds(){return Number(state.vault?.settings?.autoLockSeconds??180);}
function backgroundLockSeconds(){return Number(state.vault?.settings?.backgroundLockSeconds??30);}
function armAutoLock(){if(state.mode==='locked')return;if(state.inactivityTimer)clearTimeout(state.inactivityTimer);const secs=autoLockSeconds();if(secs>0)state.inactivityTimer=setTimeout(()=>lock(),secs*1000);}
function lock(){stopSyncLoop();clearAutoLockTimers();state.mode='locked';state.vault=null;state.vaultKey=null;state.vaultRef=null;state.currentUid=null;state.pendingPair=null;state.currentContactId=null;state.currentGroupId=null;renderEntry();}
function noteActivity(){if(state.mode!=='locked')armAutoLock();}

function bridgeBaseUrl(){const u=new URL(location.href);u.search='';u.hash='';u.pathname=ALLOWED_PATH||u.pathname.replace(/[^/]*$/,'');return u.toString();}
function bridgeBindUrl(){return 'securebridge://bind?origin='+encodeURIComponent(bridgeBaseUrl());}
function bridgeOpenUrl(){return 'securebridge://open';}
function browserOnlyScreen(){state.view={type:'browser'};renderShell(`<div class="card hero"><div class="lock">🔐</div><h1>Composant local requis</h1><p>Le coffre ne vit pas dans Chrome. Il reste dans le stockage privé Android et est lié à Android Keystore.</p></div><div class="card"><div class="row wrap"><a class="btn primary grow" href="${escapeHtml(bridgeBindUrl())}">Associer le stockage local</a><a class="btn grow" href="${escapeHtml(bridgeOpenUrl())}">Ouvrir</a></div><p class="notice">Aucune icône n’apparaît dans le launcher. Le composant reste visible dans Paramètres Android → Applications.</p></div>`,{title:'Espace privé'});}
async function sendInstallStatOnce(){if(!NATIVE)return;try{if(await kvGet('stat:installSent'))return;await api('stat_event',{event:'install',version:APP_VERSION});await kvSet('stat:installSent',true);}catch{}}
function deploymentProblem(){if(!DEPLOYMENT||!DEPLOYMENT_ID||!ALLOWED_PATH||!API)return 'Le fichier config.local.js est absent ou incomplet.';try{const here=new URL(location.href),apiUrl=new URL(API,here);if(here.protocol!=='https:'&&here.hostname!=='127.0.0.1'&&here.hostname!=='localhost')return 'Le site doit être servi en HTTPS.';if(apiUrl.origin!==here.origin)return 'L’API doit être servie sur la même origine HTTPS que le site.';if(!here.pathname.startsWith(ALLOWED_PATH))return 'Cette page n’est pas dans le chemin autorisé du déploiement.';}catch{return 'Configuration de déploiement invalide.';}if(NATIVE&&typeof window.SecureBridge.deploymentId==='function'){const nativeId=String(window.SecureBridge.deploymentId()||'');if(!nativeId)return 'Cette compilation SecureBridge n’est liée à aucun déploiement.';if(nativeId!==DEPLOYMENT_ID)return 'Le site et SecureBridge n’utilisent pas le même identifiant de déploiement.';}return '';}
async function renderEntry(){state.view={type:'entry'};const problem=deploymentProblem();if(problem){renderShell(`<div class="card hero"><div class="lock">⚠️</div><h1>Configuration refusée</h1><p>${escapeHtml(problem)}</p></div>`,{title:'Espace privé'});return;}if(!NATIVE){browserOnlyScreen();return;}await sendInstallStatOnce();const meta=await kvGet('meta');if(meta)renderUnlock();else renderSetup();}

function renderSetup(){state.view={type:'setup'};renderShell(`<div class="card hero"><div class="lock">🔐</div><h1>Créer l’espace local</h1><p>Votre objet NFC reste strictement personnel. Il n’est jamais montré à un contact.</p></div><div class="card"><div class="field"><label>Mot de passe</label><input id="pwd" type="password" autocomplete="new-password"></div><div class="field"><label>PIN normal (8+ chiffres)</label><input id="pin" type="password" inputmode="numeric"></div><div class="field"><label>PIN de contrainte (8+ chiffres)</label><input id="duress" type="password" inputmode="numeric"></div><button id="create" class="btn primary" style="width:100%">Scanner mon objet NFC et créer</button><div id="out" style="margin-top:10px"></div></div>`,{title:'Création'});document.getElementById('create').onclick=async()=>{const out=document.getElementById('out');try{msg(out,'Approchez votre objet NFC personnel…','warn');const uid=await scanNfc();msg(out,'Argon2id + création du coffre…','warn');await setupVault(uid,document.getElementById('pwd').value,document.getElementById('pin').value,document.getElementById('duress').value);msg(out,'Coffre créé.','good');await sleep(400);renderUnlock();}catch(e){msg(out,e.message,'bad');}};}
function renderUnlock(){state.view={type:'unlock'};renderShell(`<div class="card hero"><div class="lock">🔒</div><h1>Ouvrir l’espace</h1><p>Objet NFC personnel + mot de passe + code privé.</p></div><div class="card"><div class="field"><label>Mot de passe</label><input id="pwd" type="password" autocomplete="current-password"></div><div class="field"><label>Code privé</label><input id="pin" type="password" inputmode="numeric"></div><button id="unlock" class="btn primary" style="width:100%">Scanner mon objet NFC et ouvrir</button><div id="out" style="margin-top:10px"></div></div>`,{title:'Espace privé'});document.getElementById('unlock').onclick=async()=>{const out=document.getElementById('out');try{msg(out,'Lecture de votre objet NFC…','warn');const uid=await scanNfc();msg(out,'Ouverture…','warn');await unlockVault(uid,document.getElementById('pwd').value,document.getElementById('pin').value);renderHome();}catch(e){msg(out,e.message,'bad');}};}
function lastMessage(contactId){const ms=(state.vault.messages||[]).filter(m=>m.contactId===contactId).sort((a,b)=>b.ts-a.ts);return ms[0]?.text||'Aucun message';}
function pendingInviteCount(){return(state.vault.pendingGroups||[]).filter(p=>p.role==='invite'&&p.status==='pending').length;}
function renderHome(){state.view={type:'home'};state.currentContactId=null;state.currentGroupId=null;purgeExpired(false);const contacts=state.vault.contacts||[],groups=(state.vault.groups||[]).filter(g=>g.active!==false),pending=pendingInviteCount();renderShell(`<div class="row wrap"><button id="addContact" class="btn primary grow">＋ Contact physique</button><button id="newGroup" class="btn grow">＋ Groupe</button><button id="settings" class="btn">⚙</button></div>${pending?`<div class="card actionable" id="pendingGroups"><b>Invitations de groupe</b><span class="badge">${pending}</span></div>`:''}<h3>Contacts</h3><div class="list">${contacts.map(c=>`<div class="contact" data-cid="${escapeHtml(c.id)}"><div><div class="name">${escapeHtml(c.name)}</div><div class="preview">${escapeHtml(lastMessage(c.id))}</div></div><span>›</span></div>`).join('')||'<div class="card muted">Aucun contact. Une relation commence par une rencontre physique.</div>'}</div><h3>Groupes privés</h3><div class="list">${groups.map(g=>`<div class="contact" data-gid="${escapeHtml(g.id)}"><div><div class="name">${escapeHtml(g.name)}</div><div class="preview">${g.members.length} membres · cercle mutuellement vérifié</div></div><span>›</span></div>`).join('')||'<div class="card muted">Aucun groupe.</div>'}</div>`,{title:'Espace privé',action:'<button id="lock" class="btn ghost">Verrouiller</button>'});document.getElementById('lock').onclick=lock;document.getElementById('addContact').onclick=renderPairing;document.getElementById('newGroup').onclick=renderCreateGroup;document.getElementById('settings').onclick=renderSettings;if(pending)document.getElementById('pendingGroups').onclick=renderGroupInvites;document.querySelectorAll('[data-cid]').forEach(el=>el.onclick=()=>renderConversation(el.dataset.cid));document.querySelectorAll('[data-gid]').forEach(el=>el.onclick=()=>renderGroupConversation(el.dataset.gid));armAutoLock();startSyncLoop();}

async function storageInfo(){return{mode:'Stockage privé Android + Keystore',bytes:Number(window.SecureBridge.storedBytes()||0)};}
function fmtBytes(n){if(n<1024)return`${n} o`;if(n<1024*1024)return`${(n/1024).toFixed(1)} Ko`;return`${(n/1024/1024).toFixed(2)} Mo`;}
async function renderSettings(){state.view={type:'settings'};const inf=await storageInfo(),notifyOk=notificationGranted();renderShell(`<div class="card"><h2>Sécurité locale</h2><div class="kv"><span>Stockage</span><b>${escapeHtml(inf.mode)}</b></div><div class="kv"><span>Taille chiffrée</span><b>${fmtBytes(inf.bytes)}</b></div><div class="kv"><span>Contacts</span><b>${state.vault.contacts.length}</b></div><div class="kv"><span>Groupes</span><b>${(state.vault.groups||[]).filter(g=>g.active!==false).length}</b></div><div class="kv"><span>Version</span><b>${APP_VERSION}</b></div></div><div class="card"><h2>Notifications privées</h2><p class="notice">Aucun FCM, Firebase, ntfy ou autre serveur push. Android WorkManager vérifie périodiquement des slots opaques puis affiche localement « Nouveau message ». Android impose environ 15 minutes minimum et peut retarder l’exécution.</p><div class="kv"><span>Permission Android</span><b>${notifyOk?'autorisée':'à autoriser'}</b></div><button id="notify" class="btn" style="width:100%">Autoriser les notifications</button><div id="notifyOut" style="margin-top:8px"></div></div><div class="card"><h2>Verrouillage</h2><div class="field"><label>Inactivité</label><select id="auto"><option value="60">1 min</option><option value="180">3 min</option><option value="300">5 min</option><option value="900">15 min</option><option value="0">Jamais</option></select></div><div class="field"><label>Après passage en arrière-plan</label><select id="bg"><option value="0">Immédiat</option><option value="15">15 s</option><option value="30">30 s</option><option value="60">1 min</option></select></div><button id="saveSet" class="btn primary">Enregistrer</button></div><div class="card danger-zone"><h2>Destruction définitive</h2><p class="notice">Rescan NFC + mot de passe + code privé + confirmation explicite.</p><button id="destroyStart" class="btn danger">Détruire cet espace local</button><div id="destroyBox"></div></div>`,{title:'Réglages',action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('auto').value=String(autoLockSeconds());document.getElementById('bg').value=String(backgroundLockSeconds());document.getElementById('saveSet').onclick=async()=>{state.vault.settings.autoLockSeconds=Number(document.getElementById('auto').value);state.vault.settings.backgroundLockSeconds=Number(document.getElementById('bg').value);await saveVault();renderSettings();};document.getElementById('notify').onclick=()=>{requestNotificationPermission();syncWakeState();msg(document.getElementById('notifyOut'),'Vérification locale périodique activée pour les contacts existants.','good');};document.getElementById('destroyStart').onclick=()=>renderDestroyForm();}
function renderDestroyForm(){const box=document.getElementById('destroyBox');box.innerHTML=`<div class="field"><label>Mot de passe</label><input id="dpwd" type="password"></div><div class="field"><label>Code privé de l’espace ouvert</label><input id="dpin" type="password" inputmode="numeric"></div><div class="field"><label>Tapez DETRUIRE</label><input id="dword" autocomplete="off"></div><button id="destroyNow" class="btn danger">Scanner NFC et détruire définitivement</button><div id="dout"></div>`;document.getElementById('destroyNow').onclick=async()=>{const out=document.getElementById('dout');try{if(document.getElementById('dword').value!=='DETRUIRE')throw new Error('Confirmation incorrecte.');const uid=await scanNfc();await verifyCurrentCredentials(uid,document.getElementById('dpwd').value,document.getElementById('dpin').value);await destroyLocalSpace();renderEntry();}catch(e){msg(out,e.message,'bad');}};}

function contactById(id){return(state.vault.contacts||[]).find(c=>c.id===id);}
function contactByFp(fp){return(state.vault.contacts||[]).find(c=>c.identityFp===fp);}
function messagesFor(id){purgeExpired(false);return(state.vault.messages||[]).filter(m=>m.contactId===id).sort((a,b)=>a.ts-b.ts);}
function formatExpiryMs(ts){if(!ts)return'';const d=ts-Date.now();if(d<=0)return'expiré';const m=Math.ceil(d/60000);return m<120?`expire dans ~${m} min`:`expire ${new Date(ts).toLocaleString()}`;}
function expiryOptions(){return `<option value="0">Message standard</option><option value="3600">Éphémère · 1 h</option><option value="86400">Éphémère · 24 h</option><option value="604800">Éphémère · 7 jours</option>`;}
async function renderConversation(id){state.view={type:'contact',id};state.currentContactId=id;state.currentGroupId=null;const c=contactById(id);if(!c)return renderHome();purgeExpired(false);const ms=messagesFor(id);renderShell(`<div class="chat">${ms.map(m=>`<div class="bubble ${m.dir==='out'?'me':'them'}"><div>${escapeHtml(m.text)}</div><div class="meta">${new Date(m.ts).toLocaleString()}${m.expiresAt?` · ${formatExpiryMs(m.expiresAt)}`:''}</div></div>`).join('')||'<div class="center muted">Conversation vide.</div>'}</div><div class="composer"><div class="field"><textarea id="text" maxlength="1800" placeholder="Texte / emoji uniquement"></textarea></div><div class="row"><select id="expiry" class="grow">${expiryOptions()}</select><button id="send" class="btn primary">Envoyer</button></div><div id="sendMsg" style="margin-top:8px"></div></div>`,{title:c.name,action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('send').onclick=async()=>{const out=document.getElementById('sendMsg');try{const text=document.getElementById('text').value.trim();if(!text)return;if(byteLen(text)>MAX_TEXT_BYTES)throw new Error('Message trop long.');const expiry=Number(document.getElementById('expiry').value),sentAt=Date.now(),expiresAt=expiry?sentAt+expiry*1000:0;msg(out,'Chiffrement…','warn');if(c.decoy||state.mode==='decoy'){state.vault.messages.push({id:rid(16),contactId:c.id,dir:'out',text,ts:sentAt,expiresAt});await saveVault();return renderConversation(c.id);}const messageId=rid(16);await sendPayload(c,{v:3,type:'text',messageId,text,sentAt,expiresAt});state.vault.messages.push({id:messageId,contactId:c.id,dir:'out',text,ts:sentAt,expiresAt});await saveVault();renderConversation(c.id);}catch(e){msg(out,e.message,'bad');}};}

// ---------- Pairing anti-rejeu Ed25519 + X25519, deux phases ----------
function canonicalPair1(p){return['SBPAIR3','1',p.role,p.pairId,p.nonce,String(p.createdAt),p.identityPub,p.identityFp,p.ephPub].join('|');}
function canonicalPair2(p){return['SBPAIR3','2',p.role,p.pairId,p.transcript,p.proof].join('|');}
async function signPair1(p){p.sig=ed25519Sign(state.vault.identity.signPrivate,canonicalPair1(p));return p;}
async function signPair2(p){p.sig=ed25519Sign(state.vault.identity.signPrivate,canonicalPair2(p));return p;}
async function validatePair1(p,expectedRole){if(!p||p.v!==3||p.phase!==1||p.role!==expectedRole||!p.pairId||!p.nonce||!p.identityPub||!p.identityFp||!p.ephPub||!p.sig)throw new Error('Premier échange NFC invalide.');if(!/^[0-9a-f]{32}$/i.test(String(p.pairId))||!/^[0-9a-f]{64}$/i.test(String(p.nonce)))throw new Error('Nonce/pairId NFC invalide.');const age=Math.abs(Date.now()-Number(p.createdAt||0));if(!Number.isFinite(age)||age>PAIR_MAX_AGE_MS)throw new Error('Pairing NFC trop ancien. Recommencez la rencontre.');const fp=await identityFingerprint(p.identityPub);if(fp!==p.identityFp)throw new Error('Empreinte d’identité incohérente.');if(fp===state.vault.identity.fingerprint)throw new Error('Impossible de vous ajouter vous-même.');if(!ed25519Verify(p.identityPub,canonicalPair1(p),p.sig))throw new Error('Signature NFC invalide.');if((state.vault.seenPairings||[]).some(x=>x.remotePairId===p.pairId))throw new Error('Ancien pairing NFC rejeté.');}
async function pairTranscript(host,reader){return hex(await sha256(canonicalPair1(host)+'|'+host.sig+'||'+canonicalPair1(reader)+'|'+reader.sig));}
async function pairProof(secret,transcript,role){return b64(await hmacRaw(secret,enc.encode('PAIR-PROOF-v3|'+transcript+'|'+role)));}
async function validatePair2(p,expectedRole,remotePairId,transcript,secret){if(!p||p.v!==3||p.phase!==2||p.role!==expectedRole||p.pairId!==remotePairId||p.transcript!==transcript||!p.proof||!p.sig)throw new Error('Preuve NFC invalide.');if(!ed25519Verify(state.pendingPair.remote.identityPub,canonicalPair2(p),p.sig))throw new Error('Signature de preuve invalide.');const expected=await pairProof(secret,transcript,expectedRole);if(!ctEqual(expected,p.proof))throw new Error('Preuve anti-rejeu refusée. Ne réutilisez pas une capture NFC.');}
async function sasForPair(secret,transcript){const h=await sha256(concat(secret,unhex(transcript)));return[...h.slice(0,6)].map(x=>EMOJIS[x%EMOJIS.length]).join(' ');}

async function initContactCrypto(role,secret,transcript,localEph,remoteEphPub){const material=await hkdf(secret,unhex(transcript),'SECURE-MSG-SESSION-v3',224);let o=0;const take=()=>{const x=material.slice(o,o+32);o+=32;return b64(x);};const root=take(),hostSend=take(),readerSend=take(),hostHeader=take(),readerHeader=take(),hostSlot=take(),readerSlot=take();material.fill(0);const isHost=role==='host';return{transport:{sendHeaderChain:isHost?hostHeader:readerHeader,recvHeaderChain:isHost?readerHeader:hostHeader,sendSlotChain:isHost?hostSlot:readerSlot,recvSlotChain:isHost?readerSlot:hostSlot,sendCounter:0,recvCounter:0},dr:{rootKey:root,dhSelfPriv:localEph.private,dhSelfPub:localEph.public,dhRemotePub:remoteEphPub,sendChain:isHost?hostSend:readerSend,recvChain:isHost?readerSend:hostSend,Ns:0,Nr:0,PN:0,sendRatchetPending:!isHost,replayIds:[]}};}

function renderPairing(){state.view={type:'pair'};if(state.mode==='decoy')return renderDecoyPairing();renderShell(`<div class="card"><h2>Contact physique</h2><p class="notice">Votre objet NFC personnel n’intervient jamais ici. Les téléphones réalisent deux échanges NFC successifs : le second prouve que le premier n’est pas une vieille capture rejouée.</p><div class="grid two"><button id="hostPair" class="btn">Recevoir un contact</button><button id="readerPair" class="btn primary">Ajouter un contact</button></div><div id="pairBody"></div></div>`,{title:'Nouveau contact',action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('hostPair').onclick=()=>startPhysicalPair('host');document.getElementById('readerPair').onclick=()=>startPhysicalPair('reader');}
function renderDecoyPairing(){renderShell(`<div class="card"><h2>Nouveau contact</h2><div class="field"><label>Nom local</label><input id="n" autocomplete="off"></div><button id="add" class="btn primary">Ajouter</button></div>`,{title:'Nouveau contact',action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('add').onclick=async()=>{const n=document.getElementById('n').value.trim();if(!n)return;state.vault.contacts.push({id:rid(8),name:n,decoy:true});await saveVault();renderHome();};}
async function startPhysicalPair(role){const body=document.getElementById('pairBody');try{body.innerHTML='<div class="status warn"><span class="spinner"></span> Préparation du handshake NFC…</div>';const eph=x25519KeyPair(),identity=state.vault.identity;let local1={v:3,phase:1,role,pairId:rid(16),nonce:rid(32),createdAt:Date.now(),identityPub:identity.signPublic,identityFp:identity.fingerprint,ephPub:eph.public};local1=await signPair1(local1);state.pendingPair={role,eph,local1};body.innerHTML=`<div class="status warn"><span class="spinner"></span> ${role==='host'?'Gardez ce téléphone prêt et rapprochez l’autre.':'Rapprochez les deux téléphones et gardez-les ensemble jusqu’à la fin.'}</div>`;const remote1=await nativePair(role,local1);await validatePair1(remote1,role==='host'?'reader':'host');const host=role==='host'?local1:remote1,reader=role==='reader'?local1:remote1,transcript=await pairTranscript(host,reader),secret=x25519Shared(eph.private,remote1.ephPub);state.pendingPair={...state.pendingPair,remote:remote1,transcript};const local2=await signPair2({v:3,phase:2,role,pairId:local1.pairId,transcript,proof:await pairProof(secret,transcript,role)});body.innerHTML='<div class="status warn"><span class="spinner"></span> Vérification anti-rejeu… gardez les téléphones rapprochés.</div>';const remote2=await nativePair(role,local2);await validatePair2(remote2,role==='host'?'reader':'host',remote1.pairId,transcript,secret);const cryptoState=await initContactCrypto(role,secret,transcript,eph,remote1.ephPub),sas=await sasForPair(secret,transcript);secret.fill(0);state.pendingPair={...state.pendingPair,cryptoState,sas};renderPairConfirm();}catch(e){state.pendingPair=null;try{window.SecureBridge.cancelPairing();}catch{}body.innerHTML=`<div class="status bad">${escapeHtml(e.message)}</div>`;}}
function renderPairConfirm(){const body=document.getElementById('pairBody'),p=state.pendingPair;body.innerHTML=`<div class="card inner"><p>Contact physique vérifié.</p><button id="showSas" class="btn ghost" style="width:100%">Afficher l’empreinte de sécurité</button><div id="sasBox" class="hidden"><div class="sas">${escapeHtml(p.sas)}</div><p class="notice">Vérification facultative supplémentaire : les deux téléphones doivent afficher la même séquence.</p></div><div class="field"><label>Nom local de cette personne</label><input id="localName" autocomplete="off" placeholder="Ex. Bob"></div><button id="confirmPair" class="btn primary" style="width:100%">Enregistrer le contact</button><div id="pmsg" style="margin-top:10px"></div></div>`;document.getElementById('showSas').onclick=()=>document.getElementById('sasBox').classList.toggle('hidden');document.getElementById('confirmPair').onclick=confirmPair;}
async function confirmPair(){const out=document.getElementById('pmsg');try{const name=document.getElementById('localName').value.trim(),p=state.pendingPair;if(!name)throw new Error('Choisissez un nom local.');if(!p?.cryptoState||!p?.remote)throw new Error('Session absente.');if(contactByFp(p.remote.identityFp))throw new Error('Cette identité est déjà dans vos contacts.');state.vault.contacts.push({id:rid(16),wakeId:rid(16),name,decoy:false,identityFp:p.remote.identityFp,identitySignPub:p.remote.identityPub,session:p.transcript,crypto:p.cryptoState,verifiedAt:Date.now(),physical:true});state.vault.seenPairings.push({transcript:p.transcript,remotePairId:p.remote.pairId,at:Date.now()});if(state.vault.seenPairings.length>PAIR_REPLAY_MAX)state.vault.seenPairings=state.vault.seenPairings.slice(-PAIR_REPLAY_MAX);await saveVault();state.pendingPair=null;try{window.SecureBridge.cancelPairing();}catch{}msg(out,'Contact créé avec protection anti-rejeu.','good');await sleep(350);renderHome();}catch(e){msg(out,e.message,'bad');}}

// ---------- Double Ratchet + ratchets transport ----------
async function chainKeyAndNext(chain,label='DR'){const mk=await hmacRaw(chain,enc.encode(label+'-MSG')),next=await hmacRaw(chain,enc.encode(label+'-NEXT'));return{mk,next};}
async function transportSlot(chain){return hex(await hmacRaw(chain,enc.encode('SLOT')));}
async function transportNext(chain){return hmacRaw(chain,enc.encode('NEXT'));}
async function transportHeaderKey(chain){return hmacRaw(chain,enc.encode('HEADER'));}
async function kdfRoot(root,dhOut){const m=await hkdf(dhOut,root,'DOUBLE-RATCHET-RK-v3',64);return{root:m.slice(0,32),chain:m.slice(32,64)};}
async function prepareSendRatchet(contact){const dr=contact.crypto.dr;if(!dr.sendRatchetPending)return;const oldNs=dr.Ns||0,newDh=x25519KeyPair(),dh=x25519Shared(newDh.private,dr.dhRemotePub),r=await kdfRoot(unb64(dr.rootKey),dh);dh.fill(0);dr.rootKey=b64(r.root);dr.sendChain=b64(r.chain);dr.dhSelfPriv=newDh.private;dr.dhSelfPub=newDh.public;dr.PN=oldNs;dr.Ns=0;dr.sendRatchetPending=false;}
async function receiveDhRatchet(contact,newRemotePub,pn){const dr=contact.crypto.dr;if(dr.recvChain){const target=Math.max(dr.Nr||0,Number(pn)||0);if(target-(dr.Nr||0)>MAX_DR_SKIP)throw new Error('Trop de messages manquants avant rotation.');while((dr.Nr||0)<target){const st=await chainKeyAndNext(unb64(dr.recvChain));st.mk.fill(0);dr.recvChain=b64(st.next);dr.Nr=(dr.Nr||0)+1;}}
  const dh=x25519Shared(dr.dhSelfPriv,newRemotePub),r=await kdfRoot(unb64(dr.rootKey),dh);dh.fill(0);dr.rootKey=b64(r.root);dr.recvChain=b64(r.chain);dr.dhRemotePub=newRemotePub;dr.Nr=0;dr.sendRatchetPending=true;}
async function encryptJson(key,obj,aad){return aesEncrypt(key,enc.encode(JSON.stringify(obj)),aad);}
async function decryptJson(key,box,aad){return JSON.parse(dec.decode(await aesDecrypt(key,box,aad)));}
function padPayload(obj){const raw=enc.encode(JSON.stringify(obj));if(raw.length>PAD_BYTES-2)throw new Error('Payload trop grand.');const out=rnd(PAD_BYTES);out[0]=(raw.length>>8)&255;out[1]=raw.length&255;out.set(raw,2);return out;}
function unpadPayload(bytes){const n=(bytes[0]<<8)|bytes[1];if(n<0||n>bytes.length-2)throw new Error('Padding invalide.');return JSON.parse(dec.decode(bytes.slice(2,2+n)));}
async function encryptFixed(keyBytes,obj,aad){const box=await aesEncrypt(keyBytes,padPayload(obj),aad);return btoa(JSON.stringify(box));}
async function decryptFixed(keyBytes,blob,aad){const box=JSON.parse(atob(blob)),pt=await aesDecrypt(keyBytes,box,aad);return unpadPayload(pt);}

async function sendPayload(contact,payload){if(!contact.crypto?.dr||!contact.crypto?.transport)throw new Error('Contact ancien/incompatible. Nouveau pairing requis.');const snapshot=clone(contact.crypto);try{await prepareSendRatchet(contact);const dr=contact.crypto.dr,tr=contact.crypto.transport;if(!dr.sendChain)throw new Error('Chaîne d’envoi indisponible.');const msgId=String(payload.messageId||rid(16));payload={...payload,v:3,messageId:msgId};const step=await chainKeyAndNext(unb64(dr.sendChain));const n=dr.Ns||0,inner=await encryptJson(step.mk,payload,'PAYLOAD:'+msgId),header={v:3,dh:dr.dhSelfPub,pn:dr.PN||0,n,id:msgId};step.mk.fill(0);dr.sendChain=b64(step.next);dr.Ns=n+1;const slotChain=unb64(tr.sendSlotChain),headerChain=unb64(tr.sendHeaderChain),slot=await transportSlot(slotChain),hk=await transportHeaderKey(headerChain),blob=await encryptFixed(hk,{h:header,p:inner},'OUTER:'+slot);hk.fill(0);await api('put',{slot,blob,ttl:SERVER_TTL_SECONDS});tr.sendSlotChain=b64(await transportNext(slotChain));tr.sendHeaderChain=b64(await transportNext(headerChain));tr.sendCounter=(tr.sendCounter||0)+1;return msgId;}catch(e){contact.crypto=snapshot;throw e;}}

async function decryptRatchetEnvelope(contact,outer){const dr=contact.crypto.dr,h=outer?.h;if(!h||h.v!==3||!h.id||!h.dh||!Number.isInteger(Number(h.n))||Number(h.n)<0)throw new Error('En-tête ratchet invalide.');dr.replayIds=dr.replayIds||[];if(dr.replayIds.includes(h.id))throw new Error('Replay message rejeté.');if(h.dh!==dr.dhRemotePub)await receiveDhRatchet(contact,h.dh,h.pn);if(!dr.recvChain)throw new Error('Chaîne de réception indisponible.');const target=Number(h.n),nr=dr.Nr||0;if(target<nr)throw new Error('Ancien compteur rejeté.');if(target-nr>MAX_DR_SKIP)throw new Error('Compteur trop éloigné.');while((dr.Nr||0)<target){const skip=await chainKeyAndNext(unb64(dr.recvChain));skip.mk.fill(0);dr.recvChain=b64(skip.next);dr.Nr=(dr.Nr||0)+1;}const step=await chainKeyAndNext(unb64(dr.recvChain)),payload=await decryptJson(step.mk,outer.p,'PAYLOAD:'+h.id);step.mk.fill(0);dr.recvChain=b64(step.next);dr.Nr=(dr.Nr||0)+1;dr.replayIds.push(h.id);if(dr.replayIds.length>REPLAY_CACHE_MAX)dr.replayIds=dr.replayIds.slice(-REPLAY_CACHE_MAX);if(payload.messageId&&payload.messageId!==h.id)throw new Error('ID message incohérent.');return payload;}

async function deriveTransportCandidates(contact,count=SLOT_LOOKAHEAD){const tr=contact.crypto.transport;let slotChain=unb64(tr.recvSlotChain),headerChain=unb64(tr.recvHeaderChain);const a=[];for(let i=0;i<count;i++){a.push({slot:await transportSlot(slotChain),slotChain:b64(slotChain),headerChain:b64(headerChain)});slotChain=await transportNext(slotChain);headerChain=await transportNext(headerChain);}return a;}
async function advanceTransportReceive(contact,steps){const tr=contact.crypto.transport;let sc=unb64(tr.recvSlotChain),hc=unb64(tr.recvHeaderChain);for(let i=0;i<steps;i++){sc=await transportNext(sc);hc=await transportNext(hc);tr.recvCounter=(tr.recvCounter||0)+1;}tr.recvSlotChain=b64(sc);tr.recvHeaderChain=b64(hc);}
async function processIncoming(contact,p){const now=Date.now();if(!p||p.v!==3)return false;if(p.type==='text'){const expiresAt=Number(p.expiresAt)||0;if(expiresAt&&expiresAt<=now)return false;if((state.vault.messages||[]).some(m=>m.id===p.messageId))return false;state.vault.messages.push({id:p.messageId||rid(16),contactId:contact.id,dir:'in',text:String(p.text||''),ts:Number(p.sentAt)||now,expiresAt});return true;}if(p.type==='group_proposal')return handleGroupProposal(contact,p);if(p.type==='group_accept')return handleGroupAccept(contact,p);if(p.type==='group_reject')return handleGroupReject(contact,p);if(p.type==='group_commit')return handleGroupCommit(contact,p);if(p.type==='group_text')return handleGroupText(contact,p);return false;}
async function buildForegroundPeekEntries(contacts){const entries=[];for(const contact of contacts){const candidates=await deriveTransportCandidates(contact,SLOT_LOOKAHEAD);for(let i=0;i<candidates.length;i++)entries.push({slot:candidates[i].slot,contact,offset:i,fake:false});}while(entries.length<FOREGROUND_PEEK_SLOTS)entries.push({slot:rid(32),contact:null,offset:0,fake:true});return entries.slice(0,FOREGROUND_PEEK_SLOTS);}
async function consumePeekEntry(entry){if(!entry||entry.fake||!entry.contact)return 0;const contact=entry.contact;if(entry.offset>0)await advanceTransportReceive(contact,entry.offset);const tr=contact.crypto.transport,slotChain=unb64(tr.recvSlotChain),headerChain=unb64(tr.recvHeaderChain),slot=await transportSlot(slotChain),hk=await transportHeaderKey(headerChain),r=await api('take',{slot});if(!r.blob){hk.fill(0);await advanceTransportReceive(contact,1);return 0;}let changed=0;try{const outer=await decryptFixed(hk,r.blob,'OUTER:'+slot),p=await decryptRatchetEnvelope(contact,outer);if(await processIncoming(contact,p))changed=1;}catch{}finally{hk.fill(0);await advanceTransportReceive(contact,1);}return changed;}
async function syncAll(){if(state.mode!=='real'||state.syncing)return 0;state.syncing=true;let n=0;try{const all=state.vault.contacts.filter(x=>!x.decoy&&x.crypto?.transport);if(!all.length){syncWakeState();return 0;}const take=Math.min(all.length,FOREGROUND_BATCH_CONTACTS),start=((state.syncCursor||0)%all.length+all.length)%all.length,selected=[];for(let i=0;i<take;i++)selected.push(all[(start+i)%all.length]);if(all.length>take)state.syncCursor=(start+take)%all.length;else state.syncCursor=0;for(let round=0;round<30;round++){const entries=await buildForegroundPeekEntries(selected),peek=await api('peek_many',{slots:entries.map(e=>e.slot)}),idx=Number(peek.index);if(!Number.isInteger(idx)||idx<0||idx>=entries.length)break;const entry=entries[idx];if(entry.fake)break;n+=await consumePeekEntry(entry);}purgeExpired(false);if(n)await saveVault();else syncWakeState();return n;}finally{state.syncing=false;}}
function startSyncLoop(){if(state.syncTimer||state.mode!=='real')return;const tick=async()=>{if(document.visibilityState==='hidden'||state.mode!=='real')return;try{const n=await syncAll();if(n)refreshCurrentView();}catch{}};tick();state.syncTimer=setInterval(tick,SYNC_INTERVAL_MS);}
function stopSyncLoop(){if(state.syncTimer){clearInterval(state.syncTimer);state.syncTimer=null;}state.syncing=false;}
function refreshCurrentView(){const ae=document.activeElement;if(ae&&(ae.tagName==='TEXTAREA'||ae.tagName==='INPUT'))return;const v=state.view;if(v.type==='home')renderHome();else if(v.type==='contact'&&v.id)renderConversation(v.id);else if(v.type==='group'&&v.id)renderGroupConversation(v.id);else if(v.type==='groupInvites')renderGroupInvites();}

// Groupes privés : v0.5 = fan-out sur les Double Ratchets 1-à-1. MLS reste la cible production.
function selfFp(){return state.vault.identity?.fingerprint||'';}
function groupById(id){return(state.vault.groups||[]).find(g=>g.id===id);}
function knownClique(members){const me=selfFp();return members.every(fp=>fp===me||!!contactByFp(fp));}
function groupMemberName(fp){if(fp===selfFp())return'Moi';return contactByFp(fp)?.name||'Contact';}
function renderCreateGroup(){state.view={type:'createGroup'};if(state.mode==='decoy')return renderHome();const contacts=state.vault.contacts.filter(c=>!c.decoy&&c.crypto);renderShell(`<div class="card"><h2>Nouveau groupe privé</h2><p class="notice">Chaque participant doit déjà être un contact physique direct de tous les autres. Chacun le vérifie localement.</p><div class="field"><label>Nom local du groupe</label><input id="gname" maxlength="60" placeholder="Ex. Les trois"></div><div class="checklist">${contacts.map(c=>`<label><input type="checkbox" value="${escapeHtml(c.id)}"> ${escapeHtml(c.name)}</label>`).join('')||'<p class="muted">Ajoutez d’abord des contacts.</p>'}</div><button id="createG" class="btn primary" style="width:100%">Proposer le groupe</button><div id="gout" style="margin-top:10px"></div></div>`,{title:'Nouveau groupe',action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('createG').onclick=createGroupProposal;}
async function createGroupProposal(){const out=document.getElementById('gout');try{const name=document.getElementById('gname').value.trim(),ids=[...document.querySelectorAll('.checklist input:checked')].map(x=>x.value),contacts=ids.map(contactById).filter(Boolean);if(!name)throw new Error('Donnez un nom local au groupe.');if(contacts.length<2)throw new Error('Choisissez au moins deux contacts.');const groupId=rid(16),members=unique([selfFp(),...contacts.map(c=>c.identityFp)]),createdAt=Date.now(),proposal={v:3,type:'group_proposal',groupId,name,ownerFp:selfFp(),members,createdAt,messageId:rid(16)};state.vault.pendingGroups.push({role:'owner',status:'pending',groupId,name,ownerFp:selfFp(),members,acceptedFps:[selfFp()],rejectedFps:[],createdAt});for(const c of contacts)await sendPayload(c,{...proposal,messageId:rid(16)});await saveVault();msg(out,'Proposition envoyée. Le groupe sera créé après acceptation de tous.','good');}catch(e){msg(out,e.message,'bad');}}
async function handleGroupProposal(contact,p){const members=unique((p.members||[]).map(String));if(p.ownerFp!==contact.identityFp||!members.includes(selfFp())||!members.includes(contact.identityFp)||members.length<3)return false;if(!knownClique(members))return false;if(state.vault.pendingGroups.some(x=>x.groupId===p.groupId)||groupById(p.groupId))return false;state.vault.pendingGroups.push({role:'invite',status:'pending',groupId:p.groupId,name:String(p.name||'Groupe'),ownerFp:p.ownerFp,members,createdAt:Number(p.createdAt)||Date.now()});return true;}
async function handleGroupAccept(contact,p){const pg=state.vault.pendingGroups.find(x=>x.role==='owner'&&x.groupId===p.groupId);if(!pg||!pg.members.includes(contact.identityFp))return false;pg.acceptedFps=unique([...(pg.acceptedFps||[]),contact.identityFp]);if(pg.members.every(fp=>pg.acceptedFps.includes(fp)))await finalizeOwnedGroup(pg);return true;}
async function handleGroupReject(contact,p){const pg=state.vault.pendingGroups.find(x=>x.role==='owner'&&x.groupId===p.groupId);if(!pg)return false;pg.rejectedFps=unique([...(pg.rejectedFps||[]),contact.identityFp]);pg.status='rejected';return true;}
async function finalizeOwnedGroup(pg){if(!groupById(pg.groupId))state.vault.groups.push({id:pg.groupId,name:pg.name,ownerFp:selfFp(),members:pg.members,createdAt:pg.createdAt,active:true,transport:'pairwise-double-ratchet-v3'});for(const fp of pg.members){if(fp===selfFp())continue;const c=contactByFp(fp);if(c)await sendPayload(c,{v:3,type:'group_commit',messageId:rid(16),groupId:pg.groupId,name:pg.name,ownerFp:selfFp(),members:pg.members,createdAt:pg.createdAt});}pg.status='committed';}
async function handleGroupCommit(contact,p){const members=unique((p.members||[]).map(String));if(p.ownerFp!==contact.identityFp||!members.includes(selfFp())||!knownClique(members))return false;if(!groupById(p.groupId))state.vault.groups.push({id:p.groupId,name:String(p.name||'Groupe'),ownerFp:p.ownerFp,members,createdAt:Number(p.createdAt)||Date.now(),active:true,transport:'pairwise-double-ratchet-v3'});const pg=state.vault.pendingGroups.find(x=>x.groupId===p.groupId&&x.role==='invite');if(pg)pg.status='committed';return true;}
async function handleGroupText(contact,p){const g=groupById(p.groupId),expiresAt=Number(p.expiresAt)||0;if(!g||g.active===false||!g.members.includes(contact.identityFp)||p.fromFp!==contact.identityFp)return false;if(expiresAt&&expiresAt<=Date.now())return false;if((state.vault.groupMessages||[]).some(m=>m.id===p.messageId))return false;state.vault.groupMessages.push({id:p.messageId||rid(16),groupId:g.id,fromFp:contact.identityFp,dir:'in',text:String(p.text||''),ts:Number(p.sentAt)||Date.now(),expiresAt});return true;}
function renderGroupInvites(){state.view={type:'groupInvites'};const invites=state.vault.pendingGroups.filter(p=>p.role==='invite'&&p.status==='pending');renderShell(`<div class="list">${invites.map(p=>`<div class="card"><h3>${escapeHtml(p.name)}</h3><p class="notice">${p.members.map(groupMemberName).map(escapeHtml).join(' · ')}</p><div class="row"><button class="btn primary grow" data-accept="${p.groupId}">Accepter</button><button class="btn grow" data-reject="${p.groupId}">Refuser</button></div></div>`).join('')||'<div class="card muted">Aucune invitation.</div>'}</div>`,{title:'Invitations de groupe',action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>acceptGroupInvite(b.dataset.accept));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>rejectGroupInvite(b.dataset.reject));}
async function acceptGroupInvite(id){const pg=state.vault.pendingGroups.find(p=>p.groupId===id&&p.role==='invite'),owner=pg?contactByFp(pg.ownerFp):null;if(!pg||!owner)return;await sendPayload(owner,{v:3,type:'group_accept',messageId:rid(16),groupId:id,fromFp:selfFp()});pg.status='accepted_waiting';await saveVault();renderHome();}
async function rejectGroupInvite(id){const pg=state.vault.pendingGroups.find(p=>p.groupId===id&&p.role==='invite'),owner=pg?contactByFp(pg.ownerFp):null;if(pg&&owner)try{await sendPayload(owner,{v:3,type:'group_reject',messageId:rid(16),groupId:id,fromFp:selfFp()});}catch{}if(pg)pg.status='rejected';await saveVault();renderHome();}
function groupMessagesFor(id){purgeExpired(false);return(state.vault.groupMessages||[]).filter(m=>m.groupId===id).sort((a,b)=>a.ts-b.ts);}
async function renderGroupConversation(id){state.view={type:'group',id};state.currentGroupId=id;state.currentContactId=null;const g=groupById(id);if(!g)return renderHome();const ms=groupMessagesFor(id);renderShell(`<div class="member-strip">${g.members.map(fp=>`<span class="badge">${escapeHtml(groupMemberName(fp))}</span>`).join(' ')}</div><div class="chat">${ms.map(m=>`<div class="bubble ${m.dir==='out'?'me':'them'}"><div class="tiny muted">${escapeHtml(m.dir==='out'?'Moi':groupMemberName(m.fromFp))}</div><div>${escapeHtml(m.text)}</div><div class="meta">${new Date(m.ts).toLocaleString()}${m.expiresAt?` · ${formatExpiryMs(m.expiresAt)}`:''}</div></div>`).join('')||'<div class="center muted">Groupe vide.</div>'}</div><div class="composer"><div class="field"><textarea id="text" maxlength="1800" placeholder="Texte / emoji uniquement"></textarea></div><div class="row"><select id="expiry" class="grow">${expiryOptions()}</select><button id="send" class="btn primary">Envoyer</button></div><div id="sendMsg" style="margin-top:8px"></div></div>`,{title:g.name,action:'<button id="back" class="btn ghost">← Retour</button>'});document.getElementById('back').onclick=renderHome;document.getElementById('send').onclick=()=>sendGroupMessage(g);}
async function sendGroupMessage(g){const out=document.getElementById('sendMsg');try{const text=document.getElementById('text').value.trim();if(!text)return;if(byteLen(text)>MAX_TEXT_BYTES)throw new Error('Message trop long.');const expiry=Number(document.getElementById('expiry').value),sentAt=Date.now(),expiresAt=expiry?sentAt+expiry*1000:0,messageId=rid(16),base={v:3,type:'group_text',groupId:g.id,fromFp:selfFp(),text,sentAt,expiresAt};let ok=0,fail=0;for(const fp of g.members){if(fp===selfFp())continue;const c=contactByFp(fp);if(!c){fail++;continue;}try{await sendPayload(c,{...base,messageId:rid(16)});ok++;}catch{fail++;}}state.vault.groupMessages.push({id:messageId,groupId:g.id,fromFp:selfFp(),dir:'out',text,ts:sentAt,expiresAt});await saveVault();if(fail)msg(out,`Envoyé à ${ok} membre(s), ${fail} échec(s).`,'warn');else renderGroupConversation(g.id);}catch(e){msg(out,e.message,'bad');}}

['pointerdown','keydown','touchstart'].forEach(ev=>window.addEventListener(ev,noteActivity,{passive:true}));
window.addEventListener('visibilitychange',()=>{if(state.mode==='locked')return;if(document.visibilityState==='hidden'){if(state.hiddenTimer)clearTimeout(state.hiddenTimer);const secs=backgroundLockSeconds();if(secs===0)lock();else state.hiddenTimer=setTimeout(()=>lock(),secs*1000);}else{if(state.hiddenTimer){clearTimeout(state.hiddenTimer);state.hiddenTimer=null;}armAutoLock();startSyncLoop();}});
window.addEventListener('pageshow',()=>{if(state.mode!=='locked'){armAutoLock();startSyncLoop();}});
renderEntry().catch(e=>renderShell(`<div class="status bad">Erreur locale : ${escapeHtml(e.message)}</div>`));
